    public static String deDot(String s) {
        int lox = s.indexOf(LEFT_OXFORD_CHAR);
        if (lox == -1)
            return s.replace(".", "/");
        // don't de-dot inside of oxford brackets.
        //int rox = s.indexOf(RIGHT_OXFORD_CHAR);
        return s.substring(0, lox).replace(".", "/") +
               s.substring(lox);
    }

