    public static String deMangle(String s) {
        if (s.length() < 2 || s.charAt(0) != '\\')
            return s;
        if (s.charAt(1) == '=')
            s = s.substring(2);
        int l = s.length();
        if (l == 0)
            return s;
        StringBuilder sb = new StringBuilder();
        boolean sawback = false;
        for (int i = 0; i < l; i++) {
            char ch = s.charAt(i);
            if (sawback) {
                int j = SF_ESCAPES.indexOf(ch);
                if (j != -1) {
                    sb.append(SF_TRANSLATES.charAt(j));
                    sawback = false;
                    continue;
                }
                sb.append('\\');
            }
            if (ch == '\\') {
                sawback = true;
            } else {
                sawback = false;
                sb.append(ch);
            }
        }
        if (sawback)
            sb.append('\\');

        return sb.toString();
    }

